{"path": "bowling.py", "content": "class BowlingGame:
    def __init__(self):
        self.rolls = []

    def _state(self):
        """Walk the rolls; return (frame_index, rolls_in_current_frame, fill_needed, fill_rolls)."""
        i = 0
        frame = 0
        while frame < 10 and i < len(self.rolls):
            if self.rolls[i] == 10:
                i += 1
            elif i + 1 < len(self.rolls):
                i += 2
            else:
                return frame, [self.rolls[i]], i
            frame += 1
        return frame, [], i

    def roll(self, pins):
        if pins < 0:
            raise ValueError("negative roll is invalid")
        if pins > 10:
            raise ValueError("pin count exceeds pins on the lane")
        frame, current, idx = self._state()
        if frame < 10:
            if current and current[0] + pins > 10:
                raise ValueError("pin count exceeds pins on the lane")
            self.rolls.append(pins)
            return
        # Game frames done; handle fill balls.
        r = self.rolls
        start = self._tenth_start()
        first, second = r[start], r[start + 1] if start + 1 < len(r) else None
        if first == 10:
            needed = 2
        elif first + second == 10:
            needed = 1
        else:
            raise IndexError("cannot roll after game is over")
        fills = r[idx:]
        if len(fills) >= needed:
            raise IndexError("cannot roll after game is over")
        if needed == 2 and len(fills) == 1 and fills[0] != 10 and fills[0] + pins > 10:
            raise ValueError("pin count exceeds pins on the lane")
        self.rolls.append(pins)

    def _tenth_start(self):
        i = 0
        for _ in range(9):
            i += 1 if self.rolls[i] == 10 else 2
        return i

    def score(self):
        frame, current, idx = self._state()
        if frame < 10:
            raise IndexError("an incomplete game cannot be scored")
        r = self.rolls
        start = self._tenth_start()
        needed = 2 if r[start] == 10 else (1 if r[start] + r[start + 1] == 10 else 0)
        if len(r) - idx < needed:
            raise IndexError("an incomplete game cannot be scored")
        total, i = 0, 0
        for _ in range(10):
            if r[i] == 10:
                total += 10 + r[i + 1] + r[i + 2]
                i += 1
            elif r[i] + r[i + 1] == 10:
                total += 10 + r[i + 2]
                i += 2
            else:
                total += r[i] + r[i + 1]
                i += 2
        return total
